insert into public.productos (id, code, name, brand, sector, category, subcategory, short_description, description, price, previous_price, offer_active, stock, availability, regulated, caliber, condition, condition_grade, condition_notes, is_new, date_added, photo, published) values
  ('arma-1', '9MM-01', 'CZ Shadow 2 Compact', 'CZ', 'armeria', 'armas', 'pistolas', 'Shadow 2 en formato compacto', 'Versión compacta de la familia Shadow 2. La ficha del fabricante la presenta como una plataforma de tamaño reducido que conserva el enfoque deportivo de la serie. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/CZ%20SHADOW%202.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:CZ%20SHADOW%202.jpg","author":"Land68","license":"CC0"}'::jsonb, true),
  ('arma-2', '9MM-02', 'CZ Shadow 2', 'CZ', 'armeria', 'armas', 'pistolas', 'Familia Shadow · deportiva', 'Integrante de la familia Shadow, orientada por CZ al segmento deportivo. La configuración concreta puede variar según versión y mercado. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/CZ%20SHADOW%202.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:CZ%20SHADOW%202.jpg","author":"Land68","license":"CC0"}'::jsonb, true),
  ('arma-3', '9MM-03', 'CZ P-10 C', 'CZ', 'armeria', 'armas', 'pistolas', 'Línea P-10 · compacta', 'Pistola de la línea P-10 en configuración compacta. Esta ficha identifica el modelo de referencia; variantes, terminación y equipamiento deben verificarse. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/CZ%20P-10%20C%20cal.%209x19.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:CZ%20P-10%20C%20cal.%209x19.jpg","author":"Land68","license":"CC0"}'::jsonb, true),
  ('arma-4', '9MM-04', 'CZ P-10 C OR', 'CZ', 'armeria', 'armas', 'pistolas', 'P-10 C · variante OR', 'Variante P-10 C identificada como OR en la nomenclatura del modelo. Consultá con la armería qué configuración y componentes corresponden a la unidad ofrecida. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/CZ%20P-10%20C%20cal.%209x19.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:CZ%20P-10%20C%20cal.%209x19.jpg","author":"Land68","license":"CC0"}'::jsonb, true),
  ('arma-5', '9MM-05', 'CZ P-10 F', 'CZ', 'armeria', 'armas', 'pistolas', 'Línea P-10 · tamaño completo', 'Versión de tamaño completo de la familia P-10. El acabado de la imagen es ilustrativo y no identifica una variante disponible. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/CZ%20P-10%20C%20cal.%209x19.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:CZ%20P-10%20C%20cal.%209x19.jpg","author":"Land68","license":"CC0"}'::jsonb, true),
  ('arma-6', '9MM-06', 'CZ P-10 S', 'CZ', 'armeria', 'armas', 'pistolas', 'Línea P-10 · subcompacta', 'Versión subcompacta de la familia P-10. Confirmá con el comercio la variante exacta, configuración y disponibilidad. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/CZ%20P-10%20C%20cal.%209x19.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:CZ%20P-10%20C%20cal.%209x19.jpg","author":"Land68","license":"CC0"}'::jsonb, true),
  ('arma-7', '9MM-07', 'CZ 75 SP-01', 'CZ', 'armeria', 'armas', 'pistolas', 'Familia CZ 75 · SP-01', 'Modelo de tamaño completo de la conocida familia CZ 75, presentado aquí en la variante SP-01. Las especificaciones dependen de la versión comercializada. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/CZ%2075%20SP-01%20Shadow%209x19%20mm.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:CZ%2075%20SP-01%20Shadow%209x19%20mm.jpg","author":"autor en Commons","license":"CC BY-SA 4.0"}'::jsonb, true),
  ('arma-8', '9MM-08', 'CZ 75 Compact', 'CZ', 'armeria', 'armas', 'pistolas', 'Familia CZ 75 · compacta', 'Configuración compacta perteneciente a la familia CZ 75. La imagen no representa necesariamente el acabado ni los accesorios de una unidad en stock. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/CZ%2075%20SP-01%20Shadow%209x19%20mm.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:CZ%2075%20SP-01%20Shadow%209x19%20mm.jpg","author":"autor en Commons","license":"CC BY-SA 4.0"}'::jsonb, true),
  ('arma-9', '9MM-09', 'GLOCK 17 Gen5', 'GLOCK', 'armeria', 'armas', 'pistolas', 'GLOCK Gen5 · tamaño completo', 'Modelo de tamaño completo de la serie GLOCK 17, generación 5. Consultá la ficha del fabricante y verificá la configuración local antes de solicitarlo. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/GLOCK%2017%20Gen%204%20Pistol%20MOD%2045160305.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:GLOCK%2017%20Gen%204%20Pistol%20MOD%2045160305.jpg","author":"Steve Dock / MOD","license":"OGL v1.0"}'::jsonb, true),
  ('arma-10', '9MM-10', 'GLOCK 19 Gen5', 'GLOCK', 'armeria', 'armas', 'pistolas', 'GLOCK Gen5 · compacta', 'Versión compacta de la serie GLOCK 19 Gen5. Se muestra como referencia de catálogo; disponibilidad, cargadores y terminación deben confirmarse. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Glock%2019%20(transparent%20background).jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Glock%2019%20(transparent%20background).jpg","author":"U.S. Bureau of ATF","license":"Dominio público · EE. UU."}'::jsonb, true),
  ('arma-11', '9MM-11', 'GLOCK 45', 'GLOCK', 'armeria', 'armas', 'pistolas', 'GLOCK · formato crossover', 'Modelo de la familia crossover de GLOCK, identificado como G45. Esta presentación es ilustrativa y no confirma stock ni configuración. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/GLOCK%2017%20Gen%204%20Pistol%20MOD%2045160305.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:GLOCK%2017%20Gen%204%20Pistol%20MOD%2045160305.jpg","author":"Steve Dock / MOD","license":"OGL v1.0"}'::jsonb, true),
  ('arma-12', '9MM-12', 'GLOCK 34 Gen5 MOS', 'GLOCK', 'armeria', 'armas', 'pistolas', 'GLOCK Gen5 MOS · G34', 'Variante de corredera extendida de la familia GLOCK 34, con designación Gen5 MOS. Verificá con el comercio la versión y el equipamiento exactos. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/GLOCK%2017%20Gen%204%20Pistol%20MOD%2045160305.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:GLOCK%2017%20Gen%204%20Pistol%20MOD%2045160305.jpg","author":"Steve Dock / MOD","license":"OGL v1.0"}'::jsonb, true),
  ('arma-13', '9MM-13', 'GLOCK 26 Gen5', 'GLOCK', 'armeria', 'armas', 'pistolas', 'GLOCK Gen5 · subcompacta', 'Modelo subcompacto GLOCK 26 en generación 5. El fabricante lo identifica dentro de su línea 9×19; consultá la variante comercializada localmente. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Glock%2026.JPG?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Glock%2026.JPG","author":"KEN","license":"CC BY-SA 3.0"}'::jsonb, true),
  ('arma-14', '9MM-14', 'GLOCK 43X', 'GLOCK', 'armeria', 'armas', 'pistolas', 'GLOCK · línea Slimline', 'Modelo de la línea Slimline de GLOCK, identificado como 43X. La ficha es referencial: confirmá calibre, variante y disponibilidad con la armería. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Glock%2026.JPG?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Glock%2026.JPG","author":"KEN","license":"CC BY-SA 3.0"}'::jsonb, true),
  ('arma-15', '9MM-15', 'Beretta 92FS', 'Beretta', 'armeria', 'armas', 'pistolas', 'Familia Beretta 92 · 92FS', 'Pistola de tamaño completo de la familia 92, con sistema de acción doble y simple según la documentación de Beretta. La foto muestra la familia 92; verificá la variante exacta. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Beretta%2092FS%20hand%20gun.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Beretta%2092FS%20hand%20gun.jpg","author":"U.S. Bureau of ATF","license":"Dominio público · EE. UU."}'::jsonb, true),
  ('arma-16', '9MM-16', 'Beretta 92X', 'Beretta', 'armeria', 'armas', 'pistolas', 'Familia Beretta 92 · 92X', 'Versión contemporánea de la familia Beretta 92. La serie incluye distintas configuraciones; consultá cuál corresponde a la unidad disponible. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Beretta%2092FS%20hand%20gun.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Beretta%2092FS%20hand%20gun.jpg","author":"U.S. Bureau of ATF","license":"Dominio público · EE. UU."}'::jsonb, true),
  ('arma-17', '9MM-17', 'Beretta APX A1 Full Size', 'Beretta', 'armeria', 'armas', 'pistolas', 'Línea APX A1 · tamaño completo', 'Modelo de tamaño completo de la línea APX A1. Beretta publica manuales y variantes específicas de la serie; confirmá configuración y equipamiento. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Beretta-APX-9mm.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Beretta-APX-9mm.jpg","author":"Picanox","license":"CC BY-SA 4.0"}'::jsonb, true),
  ('arma-18', '9MM-18', 'SIG SAUER M17', 'SIG SAUER', 'armeria', 'armas', 'pistolas', 'Plataforma P320 · M17', 'Modelo M17 de SIG SAUER basado en la plataforma P320. La foto es una referencia visual; la unidad comercial puede diferir. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Sig%20Sauer%20M17.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Sig%20Sauer%20M17.jpg","author":"Andrew Smith / National Guard","license":"Dominio público · EE. UU."}'::jsonb, true),
  ('arma-19', '9MM-19', 'SIG SAUER P320 Full Size', 'SIG SAUER', 'armeria', 'armas', 'pistolas', 'Familia P320 · tamaño completo', 'Configuración de tamaño completo de la familia P320. Las versiones de esta plataforma pueden diferir en módulos, miras y otros componentes. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Sig%20Sauer%20M17.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Sig%20Sauer%20M17.jpg","author":"Andrew Smith / National Guard","license":"Dominio público · EE. UU."}'::jsonb, true),
  ('arma-20', '9MM-20', 'Taurus G3', 'Taurus', 'armeria', 'armas', 'pistolas', 'Taurus · serie G3', 'Modelo G3 de Taurus, presentado como pistola semiautomática de 9×19 en la información del fabricante. Confirmá variante y especificaciones de la versión local. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Glock%2019%20(9mm)%2C%20Generation%203.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Glock%2019%20(9mm)%2C%20Generation%203.jpg","author":"Agazoo","license":"Dominio público"}'::jsonb, true),
  ('arma-21', '9MM-21', 'SIG SAUER P365', 'SIG SAUER', 'armeria', 'armas', 'pistolas', 'Familia P365 · compacto', 'Modelo compacto de la familia P365, reconocida en el catálogo de SIG SAUER como una plataforma 9 mm. Existen distintas configuraciones; consultá la variante exacta. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Sig%20Sauer%20P365%20Handgun.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Sig%20Sauer%20P365%20Handgun.jpg","author":"Digitallymade","license":"CC BY-SA 4.0"}'::jsonb, true),
  ('arma-22', '9MM-22', 'Walther PDP Full Size 4.5″', 'Walther', 'armeria', 'armas', 'pistolas', 'Familia PDP · Full Size', 'Configuración Full Size de la familia PDP con longitud de cañón indicada en el nombre de referencia. Confirmá generación, equipamiento y especificaciones del ejemplar. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Walther%20PDP%20Compact%204%22.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Walther%20PDP%20Compact%204%22.jpg","author":"Fdik","license":"CC0"}'::jsonb, true),
  ('arma-23', '9MM-23', 'Walther PDP Compact 4″', 'Walther', 'armeria', 'armas', 'pistolas', 'Familia PDP · Compact', 'Configuración Compact de la familia PDP con longitud de cañón indicada en el nombre de referencia. La imagen y el acabado son ilustrativos. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Walther%20PDP%20Compact%204%22.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Walther%20PDP%20Compact%204%22.jpg","author":"Fdik","license":"CC0"}'::jsonb, true),
  ('arma-24', '9MM-24', 'Bersa TPR9', 'Bersa', 'armeria', 'armas', 'pistolas', 'Bersa · familia TPR9', 'Modelo TPR9 de Bersa, marca argentina. La ficha funciona como referencia para el showroom; consultá la configuración y disponibilidad directamente con la armería. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Bersa%20TPR9.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Bersa%20TPR9.jpg","author":"Shistorybuff","license":"CC BY-SA 4.0"}'::jsonb, true),
  ('arma-25', '9MM-25', 'Canik TP9 Elite Combat', 'Canik', 'armeria', 'armas', 'pistolas', 'Familia TP9 · Elite Combat', 'Integrante de la familia TP9 Elite Combat de Canik. El fabricante publica variantes y configuraciones específicas; confirmá los componentes y el acabado de la unidad. Modelo, acabado y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, '9×19 mm · confirmar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Glock%2019%20(9mm)%2C%20Generation%203.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Glock%2019%20(9mm)%2C%20Generation%203.jpg","author":"Agazoo","license":"Dominio público"}'::jsonb, true),
  ('esc-remington-870-fieldmaster', 'ESC-01', 'Remington 870 Fieldmaster', 'Remington', 'armeria', 'armas', 'escopetas', 'Escopeta de corredera · calibre 12', 'Versión Fieldmaster de la Remington 870, una de las escopetas de corredera más difundidas para caza y tiro deportivo. Robusta y de mantenimiento simple. Modelo, variante y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, 'Calibre 12 · consultar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Remington%20870%20Fieldmaster.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Remington%20870%20Fieldmaster.jpg","author":"Burnyburnout","license":"CC BY-SA 4.0"}'::jsonb, true),
  ('esc-remington-870-wingmaster', 'ESC-02', 'Remington 870 Wingmaster', 'Remington', 'armeria', 'armas', 'escopetas', 'Corredera clásica · madera y acero pavonado', 'La versión Wingmaster de la 870 combina culata y guardamanos de madera con acabado pavonado. Una clásica para caza. Modelo, variante y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, 'Calibre 12 · consultar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Remington%20870%20Wmaster.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Remington%20870%20Wmaster.jpg","author":"Burnyburnout","license":"CC BY-SA 4.0"}'::jsonb, true),
  ('esc-beretta-a400-xtreme-plus', 'ESC-03', 'Beretta A400 Xtreme Plus', 'Beretta', 'armeria', 'armas', 'escopetas', 'Semiautomática · calibre 12 · para caza exigente', 'Semiautomática de la familia A400 pensada para caza en condiciones duras, con recámara de 3½" y terminación resistente a la intemperie. Modelo, variante y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, 'Calibre 12 · recámara 3½"', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Beretta-A400-Xtreme-Plus.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Beretta-A400-Xtreme-Plus.jpg","author":"Picanox","license":"CC BY-SA 4.0"}'::jsonb, true),
  ('esc-beretta-a400-xplor-action', 'ESC-04', 'Beretta A400 Xplor Action', 'Beretta', 'armeria', 'armas', 'escopetas', 'Semiautomática · culata de madera', 'Versión Xplor Action de la A400, con culata de madera y cajón con terminación de color. Liviana y equilibrada para caza. Modelo, variante y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, 'Calibre 12 · consultar variante', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Beretta-A400-Xplor-Action.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Beretta-A400-Xplor-Action.jpg","author":"Picanox","license":"CC BY-SA 4.0"}'::jsonb, true),
  ('esc-beretta-1301-tactical', 'ESC-05', 'Beretta 1301 Tactical', 'Beretta', 'armeria', 'armas', 'escopetas', 'Semiautomática · calibre 12 · formato táctico', 'Escopeta semiautomática compacta de la línea 1301, de ciclo rápido y controles ampliados. Uso deportivo y de defensa conforme a la normativa vigente. Modelo, variante y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, 'Calibre 12', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Beretta%201301%20Tactical.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Beretta%201301%20Tactical.jpg","author":"autor en Commons","license":"CC BY-SA 4.0"}'::jsonb, true),
  ('esc-hatsan-escort', 'ESC-06', 'Hatsan Escort Magnum', 'Hatsan', 'armeria', 'armas', 'escopetas', 'Escopeta calibre 12 · línea Escort', 'Escopeta de la línea Escort del fabricante turco Hatsan, reconocida por su buena relación entre precio y prestaciones. Consultá la variante disponible. Modelo, variante y disponibilidad deben confirmarse con Armería Parabellum.', null, null, false, null, 'consultar', true, 'Calibre 12', 'nuevo', null, null, false, null, '{"src":"https://commons.wikimedia.org/wiki/Special:FilePath/Escort-Magnum-MPA-12ga.jpg?width=1200","sourceUrl":"https://commons.wikimedia.org/wiki/File:Escort-Magnum-MPA-12ga.jpg","author":"Picanox","license":"CC BY-SA 4.0"}'::jsonb, true),
